// Combine web + news results, drop already-seen URLs
const seenRows = $('Read Seen URLs').all().map(r => String(r.json.URL || '').trim().toLowerCase());
const seen = new Set(seenRows.filter(Boolean));

const webResp = $('Search Web for Mentions').first().json;
const newsResp = $('Search News (recent)').first().json;

// Only treat the WEB search's own error as a real failure.
// The news search returning "no results" is a valid empty outcome (Google News often has nothing), not a failure.
const failed = !!webResp.error;
const errorDetail = String(webResp.error || '');

const webRes = webResp.organic_results || [];
const newsRes = newsResp.news_results || newsResp.organic_results || [];

const mentions = [];
const seenThisRun = new Set();
for (const item of [...webRes, ...newsRes]) {
  const title = item.title || '';
  const link = String(item.link || item.url || '').trim();
  let snippet = String(item.snippet || '');
  if (!link) continue;
  // Google's "about this result" note often shows the real subject when the snippet is generic. Keep it as extra evidence.
  const about = item.about_this_result && item.about_this_result.source && item.about_this_result.source.description ? String(item.about_this_result.source.description).trim() : '';
  if (about && about !== snippet.trim()) snippet = (snippet + ' | About this result: ' + about.slice(0, 300)).trim();
  const key = link.toLowerCase();
  if (seen.has(key) || seenThisRun.has(key)) continue;
  seenThisRun.add(key);
  mentions.push({ title, link, snippet });
}

return [{ failed, errorDetail, mentions }];

// Merge the batch Gemini result with the mentions and needs-review mentions.
// Sentiment and risk are two separate judgements. Neither is derived from the other, and there is no confidence flag.
// If the reply is unreadable or an item is missing, that item defaults to sentiment 'unknown' and risk 'watch' so it is never lost.
const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '';
const mentions = $('Aggregate Mentions & Needs Review').first().json.mentions || [];

let classifications = [];
let parseError = '';
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  if (Array.isArray(parsed)) classifications = parsed;
  else throw new Error('not an array');
} catch (e) {
  parseError = 'AI reply unreadable, check manually';
}

// Match by number "n" when present so a skipped item cannot shift results; falls back to position.
const byN = new Map();
classifications.forEach((c, i) => { const k = (c && Number.isInteger(c.n)) ? c.n : i + 1; byN.set(k, c); });

const SENTIMENTS = ['positive', 'negative', 'neutral'];
const RISKS = ['ignore', 'watch', 'respond_now'];

return mentions.map((m, i) => {
  const c = byN.get(i + 1);
  let sentiment = 'unknown';
  let risk = 'watch';
  let reasoning = parseError || 'AI gave no answer for this mention, check manually';
  if (c) {
    const s = String(c.sentiment || '').toLowerCase().trim();
    const r = String(c.risk || '').toLowerCase().trim();
    reasoning = String(c.reasoning || '').trim();
    if (SENTIMENTS.includes(s)) sentiment = s;
    if (RISKS.includes(r)) risk = r;
    if (!SENTIMENTS.includes(s) || !RISKS.includes(r)) reasoning = (reasoning + ' (AI gave an invalid value, check manually)').trim();
  }
  return {
    json: {
      title: m.title,
      link: m.link,
      snippet: m.snippet,
      tier: m.tier,
      matchScore: m.matchScore,
      classification: { sentiment, risk, reasoning }
    }
  };
});

