// Runs once per draft. Pull the mention context from Parse Classification and add the draft text.
const p = $('Parse Classification').item.json;
const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text || '');
return { json: {
  title: p.title,
  link: p.link,
  snippet: p.snippet,
  sentiment: p.classification.sentiment,
  risk: p.classification.risk,
  reasoning: p.classification.reasoning,
  matchScore: p.matchScore,
  draftResponse: raw
} };

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '';
const mentions = $('Any Mentions?').first().json.mentions || [];

let scores = [];
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  if (Array.isArray(parsed)) scores = parsed;
  else throw new Error('not an array');
} catch (e) {
  scores = mentions.map(() => ({ score: 0.5, reasoning: 'Could not parse AI output: ' + raw.slice(0, 150) }));
}

// Match results to mentions by their number "n" when present, so a skipped or reordered item cannot shift the scores. Falls back to position.
const byN = new Map();
scores.forEach((s, i) => { const k = (s && Number.isInteger(s.n)) ? s.n : i + 1; byN.set(k, s); });

return mentions.map((m, i) => {
  const s = byN.get(i + 1) || { score: 0.5, reasoning: 'Missing score from AI response for this mention' };
  let score = Number(s.score);
  if (!Number.isFinite(score)) score = 0.5;
  score = Math.min(1, Math.max(0, score));
  let tier;
  if (score >= 0.8) tier = 'mention';
  else if (score < 0.40) tier = 'no_match';
  else tier = 'uncertain';
  return {
    json: {
      title: m.title,
      link: m.link,
      snippet: m.snippet,
      matchScore: score,
      matchReasoning: s.reasoning || '',
      tier
    }
  };
});

const item = $json;
const mention = $('Parse Primary Match').item.json;
let fetchedText = '';
let fetchFailed = false;
// Firecrawl can return success:true for an error page (404, 403 and so on). Treat any HTTP status of 400 or above as an unreadable page.
const status = item && item.data && item.data.metadata ? Number(item.data.metadata.statusCode) : 0;
const usable = item && item.success && item.data && item.data.markdown && !(status >= 400);
if (usable) {
  const full = String(item.data.markdown);
  const LIMIT = 6000;
  if (full.length <= LIMIT) {
    fetchedText = full;
  } else {
    // Long page: keep the start plus the passages around the name or company, so a mention deep in the page is not cut off.
    const HEAD = 1500;
    let out = full.slice(0, HEAD);
    const re = /nidhi.{1,3}hooda|growpido|hooda/gi;
    const ranges = [];
    let m;
    while ((m = re.exec(full)) !== null && ranges.length < 40) {
      const s = Math.max(HEAD, m.index - 500);
      const e = Math.min(full.length, m.index + 700);
      if (e <= HEAD) continue;
      const last = ranges[ranges.length - 1];
      if (last && s <= last[1]) last[1] = Math.max(last[1], e);
      else ranges.push([s, e]);
    }
    for (const r of ranges) {
      const piece = full.slice(r[0], r[1]);
      if (out.length + piece.length + 5 > LIMIT) break;
      out += '\n...\n' + piece;
    }
    fetchedText = out.slice(0, LIMIT);
  }
} else {
  fetchFailed = true;
  fetchedText = mention.snippet || '';
}
return { json: {
  title: mention.title,
  link: mention.link,
  snippet: mention.snippet,
  fetchedText,
  fetchFailed
} };

