const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '';
const ctx = $('Parse Fetched Content').item.json;

let score = 0.5, reasoning = '';
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  let parsed = JSON.parse(cleaned);
  if (Array.isArray(parsed)) parsed = parsed[0] || {};
  const n = Number(parsed.score);
  if (Number.isFinite(n)) score = Math.min(1, Math.max(0, n));
  reasoning = parsed.reasoning || '';
} catch (e) {
  reasoning = 'Could not parse AI output: ' + raw.slice(0, 150);
}

let tier;
if (score >= 0.8) tier = 'mention';
else if (score < 0.40) tier = 'no_match';
else tier = 'uncertain';

return { json: {
  title: ctx.title,
  link: ctx.link,
  snippet: ctx.snippet,
  fetchedText: ctx.fetchedText,
  matchScore: score,
  matchReasoning: reasoning,
  tier
} };

const CRISIS_KEYWORDS = ['lawsuit','lawsuits','sue','sues','sued','suing','fraud','fraudulent','scam','scams','breach','fired','terminated','arrest','arrested','investigation','court','legal action','class action','complaint filed','fbi','police','criminal','fined','penalty','shut down','shutdown','bankrupt'];
// Whole-word match: normalise the text to single-space-separated tokens, so 'sue' cannot match inside 'issue' or 'pursue'.
const text = ' ' + String($json.fetchedText || $json.snippet || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ') + ' ';
const hit = CRISIS_KEYWORDS.find(k => text.includes(' ' + k + ' '));
return { json: {
  title: $json.title,
  link: $json.link,
  snippet: $json.snippet,
  matchScore: $json.matchScore,
  matchReasoning: $json.matchReasoning,
  crisisKeywordHit: hit || null,
  tier: hit ? 'review' : 'discard'
} };

// Single source of truth about who we monitor. Every AI prompt reads this, so edit it here only.
const lines = [
